#[cfg(test)]
mod tests {
    use chrono::{TimeZone, Utc};
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;
    use rigorix_engine::effect_commitment::domain::EffectIntent;
    use uuid::Uuid;

    fn intent() -> EffectIntent {
        let mut intent = EffectIntent::new(
            Uuid::from_u128(1),
            Uuid::from_u128(2),
            3,
            IdempotencyKey::new("intent-key"),
            "payments.charge",
            "args-digest",
            "precondition-digest",
            "authority-digest",
        );
        intent.created_at = Utc.with_ymd_and_hms(2026, 10, 20, 0, 0, 0).unwrap();
        intent
    }

    #[test]
    fn test_effectintent_is_defined() {
        let intent = intent();
        assert_eq!(intent.attempt, 3);
        assert_eq!(intent.tool, "payments.charge");
        assert_eq!(intent.idempotency_key, IdempotencyKey::new("intent-key"));
        assert!(!intent.precondition_digest.is_empty());
        assert!(!intent.authority_digest.is_empty());
        assert!(!intent.created_at.timestamp().eq(&0));
    }

    #[test]
    fn test_effectintent_interacts_with_none() {
        // The intent is a serializable value object: durable records and the
        // HTTP adapter both carry it verbatim.
        let intent = intent();
        let json = serde_json::to_string(&intent).unwrap();
        let round_trip: EffectIntent = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, intent);

        // The intent digest excludes the attempt counter and timestamp, so a
        // retry of the same logical effect derives the same key.
        let mut retry = intent.clone();
        retry.attempt = 99;
        retry.created_at = Utc::now();
        assert_eq!(retry.intent_digest(), intent.intent_digest());

        // A changed payload changes the digest.
        let mut changed = intent.clone();
        changed.args_digest = "different".to_string();
        assert_ne!(changed.intent_digest(), intent.intent_digest());
    }
}
